// Demonstrates the issue with braced initializers and make functions
#include <vector>
#include <memory>
#include <initializer_list>

void demonstrate_make_vs_braces() {
    // Problematic: This calls std::vector<int>(10, 20), creating a vector of 10 elements with value 20.
    // It does NOT create a vector with two elements {10, 20}.
    auto spv1 = std::make_shared<std::vector<int>>(10, 20);

    // The make functions do not have overloads for std::initializer_list, so this is a compile error:
    // auto spv_error = std::make_shared<std::vector<int>>({10, 20}); // ERROR

    // Correct Workaround: Create an initializer_list explicitly.
    auto initList = {10, 20};
    auto spv2 = std::make_shared<std::vector<int>>(initList);
    // spv2 now correctly points to a vector with two elements: 10 and 20.
}
